function handle_community(string $a): bool {
    if($a==='contact') {
        rate('contact:'.($_SERVER['REMOTE_ADDR']??''),5,600); valid(input('website')==='','Unable to accept this submission.');
        $name=field('name',2,80); $email=strtolower(field('email',5,190)); $subject=field('subject',3,120); $message=field('message',15,3000);
        valid((bool)filter_var($email,FILTER_VALIDATE_EMAIL),'Please enter a valid email address.'); valid(input('consent')==='1','Please accept the privacy notice before sending.');
        query('INSERT INTO contact_messages(student_id,name,email,subject,message) VALUES(?,?,?,?,?)',[user()['id']??null,$name,$email,$subject,$message]);
        flash('Your enquiry has been saved for the campus team. Reference #'.db()->lastInsertId().'. No email has been sent.'); go('contact');
    }
    if($a==='organiser-decision') {
        $u=admin(); $id=(int)input('student_id'); $approve=input('decision')==='approve';
        query('UPDATE students SET role=?,organiser_requested=0,session_version=session_version+1 WHERE id=? AND role=? AND organiser_requested=1',[$approve?'organiser':'student',$id,'student']);
        audit($approve?'organiser.approved':'organiser.declined',(int)$u['id']); flash($approve?'Organiser access approved. The student can log in again to use it.':'Request declined.'); go('admin');
    }
    if($a==='resolve-contact') { admin(); query('UPDATE contact_messages SET status=? WHERE id=?',['resolved',(int)input('id')]); flash('Enquiry marked as resolved.'); go('admin'); }
    if($a==='delete-contact') { admin(); query('DELETE FROM contact_messages WHERE id=?',[(int)input('id')]); flash('Enquiry permanently deleted.'); go('admin'); }
    return false;
}
