function about_page(): void { render_header('Our story'); page_heading('BUILT FOR BELONGING','Campus is better together.','A small idea with a simple purpose: make it easier to find your people.'); ?><div class="about-grid"><section class="panel story-panel"><span class="big-star" aria-hidden="true">✳</span><h2>More than a timetable.<br><span class="serif">A place to belong.</span></h2><p>Great experiences can get lost between a disappearing story, a busy group chat and a sign-up sheet nobody can find. CampusConnect brings student communities and their plans into one shared space.</p><p>Browse a club. Find an event. Take that first small step. We believe the connections outside the classroom are an important part of the university experience.</p></section><div class="value-list"><article><span>01 / DISCOVER</span><h3>Room for every interest.</h3><p>Creative, technical, active or just curious. There is no single way to be a student.</p></article><article><span>02 / CONNECT</span><h3>Less friction. More hello.</h3><p>Clear club pages, simple memberships and an event calendar that makes sense.</p></article><article><span>03 / RESPECT</span><h3>A community with care.</h3><p>We collect only what is needed, keep private records restricted, and let you leave on your terms.</p></article></div></div><section class="section"><div class="section-title"><div><div class="eyebrow">FOUR PARTS, ONE SHARED PURPOSE</div><h2>Built as a team.</h2></div></div><div class="team-grid"><?php foreach([['01','Accounts & integration','The shared foundation and secure student experience.'],['02','Clubs & communities','Helping students discover their people.'],['03','Events & experiences','Turning an idea into a reason to show up.'],['04','Design & communication','Making every interaction clear and welcoming.']] as [$n,$t,$d]): ?><article class="panel"><span class="eyebrow">MEMBER <?=$n?></span><h3><?=e($t)?></h3><p><?=e($d)?></p></article><?php endforeach; ?></div></section><section class="banner small-banner"><div><h2>A little curiosity goes a long way.</h2><p>Let’s see where yours takes you.</p></div><a class="btn btn-light" href="<?=e(url('clubs'))?>">Find a community <?=icon('arrow')?></a></section><?php render_footer(); }
function contact_page(): void { $u=user(); render_header('Get in touch'); page_heading('WE’RE ALL EARS','Start a conversation.','A question, an idea, or a little help finding your way. We’re here.'); ?><div class="contact-layout"><aside class="contact-aside"><div class="club-symbol peach"><?=icon('mail')?></div><h2>Good things start<br>with a hello.</h2><p>Send an enquiry to the campus administration team. Your message is saved in the private administration inbox.</p><div class="contact-note"><?=icon('clock')?><p>This course project does not send email automatically. For urgent campus matters, use your institution’s official support channels.</p></div><a class="text-link" href="<?=e(url('privacy'))?>">How we look after your data <?=icon('arrow')?></a></aside><form class="panel" method="post"><?=action('contact')?><div class="form-row"><?php text_field('Your name','name','text',$u['name']??'','required minlength="2" maxlength="80" autocomplete="name"'); text_field('Email address','email','email',$u['email']??'','required maxlength="190" autocomplete="email"'); ?></div><?php text_field('What’s on your mind?','subject','text','','required minlength="3" maxlength="120"'); textarea_field('Your message','message'); ?><div class="honeypot" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="checkbox"><input type="checkbox" name="consent" value="1" required><span>I understand my details and message will be stored as described in the <a href="<?=e(url('privacy'))?>">privacy notice</a>.</span></label><button class="btn">Send enquiry <?=icon('arrow')?></button><p class="fine-print">We’ll show a reference number after your message is saved.</p></form></div><?php render_footer(); }
function privacy_page(): void { render_header('Privacy & your data'); page_heading('YOUR TRUST MATTERS','Your campus. Your information.','A clear explanation of what this project stores and why.'); ?><article class="panel prose privacy-copy"><h2>What we collect</h2><p>Your name, email address, password hash and optional profile bio; your club memberships, event RSVPs and organiser requests; club/event details you publish; and the details you submit through Contact. Passwords are stored as hashes, never as readable passwords.</p><h2>Student IDs</h2><p>Administrators maintain a list of eligible student IDs. New personal registrations must match an approved ID, and one ID can be linked to one personal account. Community requests record the registering leader ID and require administrator approval. Matching an ID confirms list eligibility; it does not independently prove identity. Existing accounts retain their access.</p><h2>Community accounts</h2><p>A community uses one shared email and password. We store the names and email addresses of at least four leaders. Anyone with the shared login can view and update this leadership list, manage the community clubs and events, change the password, and delete the account. Leader contacts are not displayed publicly. Deleting the community account also removes its leader contacts.</p><h2>Who can see it</h2><p>Club and event descriptions and organiser names are public. Your profile bio and account email are available in your account. An organiser can see the names of their own club members and event attendees, not everyone’s account details. Campus administrators can review organiser requests and contact enquiries. People operating the database can access stored records as needed to run the service.</p><h2>Sessions and security</h2><p>One necessary session cookie keeps you logged in and protects forms. There are no advertising or third-party tracking scripts. Sessions expire after 30 minutes of inactivity or eight hours total. Changing your password invalidates other sessions. We store short-lived hashed rate-limit identifiers and a minimal action audit trail to protect the service.</p><h2>Contact messages</h2><p>Enquiries are saved to an administrator-only inbox; this project does not send automatic emails. Logged-in enquiries are linked to your account and removed when you delete it. Guest enquiries are not linked to an account. Request their deletion through Contact and quote the reference number; the team must verify the request before deleting records.</p><h2>Leaving and deleting</h2><p>You can leave clubs and cancel RSVPs individually. Under Profile & security, you can delete your account after confirming your password. This removes your memberships, RSVPs and linked enquiries. If you organise clubs, deleting your account also deletes those clubs, their events and all associated memberships/RSVPs. Audit entries become anonymous. Administrators cannot delete their own administrative account through the public form.</p><h2>Retention and backups</h2><p>Contact records are retained until an administrator deletes them. The maintenance script removes expired rate limits and audit entries older than 90 days. The installation operator must schedule this script and define a backup retention policy before real deployment. Deleted data may remain in existing backups until those backups expire; do not use real student data for the classroom demonstration.</p><h2>Questions or corrections</h2><p>Update your name and bio in your account. For email corrections or a data request, use the Contact form; the administrator must verify identity before taking action. This is a course project, not an official university service.</p><a class="btn" href="<?=e(url('contact'))?>">Ask a privacy question <?=icon('arrow')?></a></article><?php render_footer(); }
function admin_page(): void { admin(); $requests=rows('SELECT id,name,email FROM students WHERE organiser_requested=1 AND role=?',['student']); $messages=rows('SELECT * FROM contact_messages ORDER BY status,created_at DESC LIMIT 100'); render_header('Campus administration'); page_heading('LOOKING AFTER THE COMMUNITY','Behind the good times.','Review organiser requests and keep the enquiry inbox moving.'); dashboard_nav('admin'); student_registry_admin_section(); community_approval_admin_section(); ?>
    <section class="section"><div class="section-title"><h2>Organiser requests</h2><span class="pill"><?=count($requests)?> awaiting review</span></div><?php if(!$requests): empty_state('All caught up.','New requests will appear here for your review.'); else: ?><div class="manage-list"><?php foreach($requests as $r): ?><div class="manage-row"><div class="avatar"><?=e(initials($r['name']))?></div><div><h3><?=e($r['name'])?></h3><span><?=e($r['email'])?></span></div><form method="post" class="row-actions"><?=action('organiser-decision')?><input type="hidden" name="student_id" value="<?=$r['id']?>"><button class="btn btn-small" name="decision" value="approve">Approve</button><button class="btn btn-ghost btn-small" name="decision" value="decline">Decline</button></form></div><?php endforeach; ?></div><?php endif; ?></section><section class="section"><div class="section-title"><h2>Enquiry inbox</h2><span>Latest 100 enquiries</span></div><?php if(!$messages)empty_state('A quiet inbox.','New contact enquiries will be stored here.'); foreach($messages as $m): ?><article class="panel enquiry"><div class="section-title"><h3>#<?=$m['id']?> · <?=e($m['subject'])?></h3><span class="pill"><?=e(ucfirst($m['status']))?></span></div><p class="fine-print">From <?=e($m['name'])?> · <?=e($m['email'])?> · <?=e(when($m['created_at']))?></p><div class="prose"><?=nl2br(e($m['message']))?></div><div class="row-actions"><?php if($m['status']==='new'): ?><form method="post"><?=action('resolve-contact')?><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-small btn-outline">Mark resolved</button></form><?php endif; ?><form method="post" data-confirm="Permanently delete this enquiry?"><?=action('delete-contact')?><input type="hidden" name="id" value="<?=$m['id']?>"><button class="text-button danger-text">Delete enquiry</button></form></div></article><?php endforeach; ?></section><?php render_footer(); }
